globals:
# Visión OpenMV: la última foto y lo último que se buscó en ella.
VIS_COLORES = {
    "rojo": (30, 100, 15, 127, 15, 127),
    "verde": (30, 100, -64, -8, -32, 32),
    "azul": (0, 30, 0, 64, -128, 0),
    "amarillo": (60, 100, -10, 10, 20, 127),
    "negro": (0, 30, -20, 20, -20, 20),
    "blanco": (75, 100, -10, 10, -10, 10),
}
VIS_GRISES = {"negro": (0, 60), "blanco": (180, 255)}
vis_gris = False
vis_img = None
vis_reloj = None
vis_fps = 0
vis_blobs = []
vis_linea = None
vis_tags = []
vis_qrs = []
vis_uart = None

def vis_iniciar(modo, tamano, ajuste, bloque):
    global vis_gris, vis_reloj
    vis_gris = modo == "gris"
    try:
        sensor.reset()
        sensor.set_pixformat(sensor.GRAYSCALE if vis_gris else sensor.RGB565)
        sensor.set_framesize(sensor.QQVGA if tamano == "qqvga" else sensor.QVGA)
        # Medio segundo para que la cámara ajuste la luz; solo una vez, al iniciar.
        sensor.skip_frames(time=500)
        if ajuste == "fijo":
            sensor.set_auto_gain(False)
            sensor.set_auto_whitebal(False)
    except Exception as error:
        rb_fail(bloque, "No se pudo iniciar la cámara: %s" % error)
    vis_reloj = time.clock()

def vis_foto(bloque):
    global vis_img, vis_fps
    if vis_reloj is None:
        rb_fail(bloque, "Inicia la cámara al iniciar")
    vis_reloj.tick()
    vis_img = sensor.snapshot()
    vis_fps = vis_reloj.fps()

def vis_imagen(bloque):
    if vis_img is None:
        rb_fail(bloque, "Toma una foto antes de buscar")
    return vis_img

def vis_umbral(color, bloque):
    if vis_gris:
        if color not in VIS_GRISES:
            rb_fail(bloque, "En grises solo se puede buscar negro o blanco")
        return VIS_GRISES[color]
    return VIS_COLORES[color]

def vis_buscar(umbral, minimo, bloque):
    global vis_blobs
    minimo = int(max(1, rb_finite(minimo, bloque)))
    encontrados = vis_imagen(bloque).find_blobs([umbral], pixels_threshold=minimo, area_threshold=minimo, merge=True)
    vis_blobs = sorted(encontrados, key=lambda blob: blob.pixels(), reverse=True)

def vis_buscar_color(color, minimo, bloque):
    vis_buscar(vis_umbral(color, bloque), minimo, bloque)

def vis_buscar_lab(l1, l2, a1, a2, b1, b2, minimo, bloque):
    if vis_gris:
        rb_fail(bloque, "Los umbrales LAB necesitan la cámara a color")
    valores = [int(rb_finite(valor, bloque)) for valor in (l1, l2, a1, a2, b1, b2)]
    vis_buscar(tuple(valores), minimo, bloque)

def vis_blob(dato, bloque):
    if not vis_blobs:
        return -1
    blob = vis_blobs[0]
    if dato == "cx":
        return blob.cx()
    if dato == "cy":
        return blob.cy()
    if dato == "dx":
        return blob.cx() - vis_imagen(bloque).width() // 2
    if dato == "w":
        return blob.w()
    if dato == "h":
        return blob.h()
    if dato == "area":
        return blob.pixels()
    return round(blob.rotation() * 180 / math.pi)

def vis_buscar_linea(color, bloque):
    global vis_linea
    vis_linea = vis_imagen(bloque).get_regression([vis_umbral(color, bloque)], robust=True)

# Ángulo: 0 = línea recta hacia adelante, positivo = inclinada a la derecha (−90 a 90).
# Desplazamiento: píxeles del centro de la imagen al punto de la línea en la fila del medio.
def vis_linea_dato(dato, bloque):
    if vis_linea is None:
        return -1 if dato == "calidad" else 0
    if dato == "calidad":
        return vis_linea.magnitude()
    if dato == "angulo":
        theta = vis_linea.theta()
        return theta if theta < 90 else theta - 180
    img = vis_imagen(bloque)
    x1, y1, x2, y2 = vis_linea.line()
    medio = img.height() / 2
    x = (x1 + x2) / 2 if y1 == y2 else x1 + (x2 - x1) * (medio - y1) / (y2 - y1)
    return round(x - img.width() / 2)

def vis_buscar_tags(bloque):
    global vis_tags
    vis_tags = sorted(vis_imagen(bloque).find_apriltags(), key=lambda tag: tag.w() * tag.h(), reverse=True)

def vis_tag(dato, bloque):
    if not vis_tags:
        return -1
    tag = vis_tags[0]
    if dato == "id":
        return tag.id()
    if dato == "cx":
        return tag.cx()
    if dato == "cy":
        return tag.cy()
    return round(tag.rotation() * 180 / math.pi)

def vis_buscar_qr(bloque):
    global vis_qrs
    vis_qrs = vis_imagen(bloque).find_qrcodes()

def vis_qr_texto():
    return vis_qrs[0].payload() if vis_qrs else ""

def vis_led(color):
    encendidos = {"rojo": (1,), "verde": (2,), "azul": (3,), "blanco": (1, 2, 3), "apagado": ()}[color]
    for numero in (1, 2, 3):
        if numero in encendidos:
            LED(numero).on()
        else:
            LED(numero).off()

def vis_uart_configurar(baudios, bloque):
    global vis_uart
    try:
        vis_uart = UART(3, int(rb_finite(baudios, bloque)))
    except (ValueError, OSError) as error:
        rb_fail(bloque, "No se pudo iniciar la UART 3: %s" % error)

# Mismo formato que la extensión UART del GIGA: «tipo:dato1,dato2*CC» con XOR en hexadecimal.
def vis_mensaje(tipo, datos, bloque):
    tipo = int(rb_finite(tipo, bloque))
    partes = []
    for dato in datos:
        dato = round(rb_finite(dato, bloque), 3)
        partes.append(str(int(dato)) if dato == int(dato) else str(dato))
    texto = "%d:%s" % (tipo, ",".join(partes))
    suma = 0
    for byte in texto.encode():
        suma ^= byte
    return "%s*%02X\n" % (texto, suma)

def vis_enviar(tipo, datos, bloque):
    if vis_uart is None:
        rb_fail(bloque, "Configura la UART 3 al iniciar")
    vis_uart.write(vis_mensaje(tipo, datos, bloque))

